package org.xingmu.tv;
import java.io.*;import java.net.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicLongArray;
import android.net.Uri;import androidx.media3.datasource.*;import androidx.media3.datasource.cache.*;import androidx.media3.exoplayer.offline.*;
/** Use four connections only when a server proves range support and a stable file validator. */
@androidx.annotation.OptIn(markerClass=androidx.media3.common.util.UnstableApi.class)
final class ParallelFileDownloader implements Downloader {
 private static final String VALIDATOR="custom_xingmu_file_validator";
 private final DownloadRequest request;private final CacheDataSource.Factory cacheFactory;private final DefaultHttpDataSource.Factory httpFactory;private final ExecutorService executor;private final Downloader fallback;private final String ua;
 private volatile boolean cancelled;private final List<CacheWriter> writers=new CopyOnWriteArrayList<>();private final List<Future<?>> jobs=new CopyOnWriteArrayList<>();
 ParallelFileDownloader(DownloadRequest request,CacheDataSource.Factory cacheFactory,DefaultHttpDataSource.Factory httpFactory,ExecutorService executor,Downloader fallback,String ua){this.request=request;this.cacheFactory=cacheFactory;this.httpFactory=httpFactory;this.executor=executor;this.fallback=fallback;this.ua=ua;}
 private static final class FileInfo{final long length;final String validator;FileInfo(long length,String validator){this.length=length;this.validator=validator;}}
 private FileInfo probe()throws IOException{String address=request.uri.toString();for(int hop=0;hop<5;hop++){if(cancelled)throw new InterruptedIOException();if(!CatalogParser.safeMediaUrl(address))return null;HttpURLConnection c=(HttpURLConnection)new URL(address).openConnection();c.setConnectTimeout(8000);c.setReadTimeout(15000);c.setInstanceFollowRedirects(false);c.setRequestProperty("User-Agent",ua);c.setRequestProperty("Accept-Encoding","identity");c.setRequestProperty("Range","bytes=0-0");try{int code=c.getResponseCode();if(code>=300&&code<400){String next=c.getHeaderField("Location");if(next==null)return null;address=new URL(new URL(address),next).toString();continue;}long[] range=RangePlan.responseRange(c.getHeaderField("Content-Range"));String validator=c.getHeaderField("ETag"),encoding=c.getHeaderField("Content-Encoding");if(validator==null||validator.startsWith("W/"))validator=c.getHeaderField("Last-Modified");if(code!=206||range==null||range[0]!=0||range[1]!=0||range[2]<8*1048576L||validator==null||validator.isEmpty()||encoding!=null&&!encoding.equalsIgnoreCase("identity"))return null;return new FileInfo(range[2],validator);}finally{c.disconnect();}}return null;}
 public void download(ProgressListener listener)throws IOException,InterruptedException{FileInfo info;try{info=probe();}catch(IOException e){if(cancelled)throw e;fallback.download(listener);return;}if(info==null){if(cancelled)throw new InterruptedException();fallback.download(listener);return;}Cache cache=cacheFactory.getCache();DataSpec base=new DataSpec.Builder().setUri(request.uri).setKey(request.customCacheKey).build();String key=cacheFactory.getCacheKeyFactory().buildCacheKey(base);String previous=cache.getContentMetadata(key).get(VALIDATOR,"");if(!previous.equals(info.validator)&&cache.getCachedBytes(key,0,info.length)>0)cache.removeResource(key);ContentMetadataMutations metadata=new ContentMetadataMutations();metadata.set(VALIDATOR,info.validator);ContentMetadataMutations.setContentLength(metadata,info.length);cache.applyContentMetadataMutations(key,metadata);
 long[][] ranges=RangePlan.split(info.length,4);AtomicLongArray downloaded=new AtomicLongArray(ranges.length);Object progressLock=new Object();CacheDataSource.Factory parallel=new CacheDataSource.Factory().setCache(cache).setCacheKeyFactory(cacheFactory.getCacheKeyFactory()).setUpstreamDataSourceFactory(()->new CheckedRangeSource(httpFactory.createDataSource(),info));CompletionService<Void> completed=new ExecutorCompletionService<>(executor);writers.clear();jobs.clear();try{for(int n=0;n<ranges.length;n++){if(cancelled)throw new InterruptedException();final int part=n;DataSpec spec=base.buildUpon().setPosition(ranges[n][0]).setLength(ranges[n][1]).setHttpRequestHeaders(Collections.singletonMap("If-Range",info.validator)).build();CacheWriter writer=new CacheWriter(parallel.createDataSourceForDownloading(),spec,new byte[128*1024],(length,bytes,newBytes)->{synchronized(progressLock){downloaded.set(part,bytes);long sum=0;for(int k=0;k<downloaded.length();k++)sum+=downloaded.get(k);if(listener!=null)listener.onProgress(info.length,sum,100f*sum/info.length);}});writers.add(writer);jobs.add(completed.submit(()->{if(cancelled)throw new InterruptedException();writer.cache();return null;}));}for(int n=0;n<ranges.length;n++){if(cancelled)throw new InterruptedException();completed.take().get();}if(cache.getCachedBytes(key,0,info.length)<info.length)throw new IOException("下载文件不完整，请重试");}catch(ExecutionException e){Throwable cause=e.getCause();if(cause instanceof IOException)throw (IOException)cause;if(cause instanceof InterruptedException)throw (InterruptedException)cause;throw new IOException("并行下载失败",cause);}catch(CancellationException e){throw new InterruptedException();}finally{for(CacheWriter writer:writers)writer.cancel();for(Future<?> job:jobs)job.cancel(true);writers.clear();jobs.clear();}}
 public void cancel(){cancelled=true;fallback.cancel();for(CacheWriter writer:writers)writer.cancel();for(Future<?> job:jobs)job.cancel(true);}
 public void remove(){fallback.remove();}
 private static final class CheckedRangeSource implements DataSource {
  private final DefaultHttpDataSource http;private final FileInfo info;CheckedRangeSource(DefaultHttpDataSource http,FileInfo info){this.http=http;this.info=info;}
  public long open(DataSpec spec)throws IOException{long result=http.open(spec);String validator=header(info.validator.startsWith("\"")?"ETag":"Last-Modified");if(http.getResponseCode()!=206||!RangePlan.matchesResponse(header("Content-Range"),spec.position,info.length,info.validator,validator)){http.close();throw new IOException("片源不再支持分段下载或文件已变化，请重新下载");}return result;}
  private String header(String name){for(Map.Entry<String,List<String>> entry:http.getResponseHeaders().entrySet())if(name.equalsIgnoreCase(entry.getKey())&&!entry.getValue().isEmpty())return entry.getValue().get(0);return null;}
  public int read(byte[] buffer,int offset,int length)throws IOException{return http.read(buffer,offset,length);}public Uri getUri(){return http.getUri();}public Map<String,List<String>> getResponseHeaders(){return http.getResponseHeaders();}public void close()throws IOException{http.close();}public void addTransferListener(TransferListener listener){http.addTransferListener(listener);}
 }
}
